import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
import { usePromotions, useProducts, useProduct } from '@salesforce/commerce-sdk-react';
import { getDisplayVariationValues } from '@salesforce/retail-react-app/app/utils/product-utils';

// See index.tsx's own note on why this is `any` rather than a structural type.
type SfccVariant = any;

const ZIMM_CART_ITEM_VARIANT_RECIPE = 'ZimmCartItemVariant';

type ItemAttributesProps = {
  includeQuantity?: boolean;
  currency?: string;
  excludeBonusLabel?: boolean;
  hideAttributeLabels?: boolean;
  /** See this file's own SFCC-270 docblock note above. */
  combineAttributeValues?: boolean;
} & Record<string, any>;

/**
 * In the context of a cart product item variant, this component renders a styled
 * list of the selected variation values as well as any promos (w/ info popover).
 */
const ItemAttributes = ({
  includeQuantity,
  currency,
  excludeBonusLabel,
  hideAttributeLabels = false,
  combineAttributeValues = false,
  ...props
}: ItemAttributesProps) => {
  const variant: SfccVariant = useItemVariant();
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});
  const { data: basket } = useCurrentBasket();
  const { currency: activeCurrency } = useCurrency();
  const promotionIds = variant.priceAdjustments?.map((adj: SfccVariant) => adj.promotionId) ?? [];
  const intl = useIntl();

  const displayBonusProductLabel = !excludeBonusLabel && variant?.bonusProductLineItem;

  // Fetch all the promotions given by price adjustments. We display this info in
  // the promotion info popover when applicable.
  const { data: res } = usePromotions(
    {
      parameters: {
        ids: promotionIds.join(','),
      },
    },
    {
      enabled: promotionIds.length > 0,
    },
  );
  const promos = res?.data || [];
  const variationValues = getDisplayVariationValues(variant?.variationAttributes, variant?.variationValues);

  // get variant info for bundled products in cart page and order history page
  const productBundleIds = variant?.bundledProductItems?.map(({ productId }: SfccVariant) => productId).join(',') ?? '';
  const { data: productBundleVariantData, isLoading: bundleVariantIsLoading } = useProducts(
    {
      parameters: {
        ids: productBundleIds,
        allImages: false,
      },
    },
    {
      enabled: Boolean(variant?.type?.bundle && productBundleIds),
      select: (result: SfccVariant) => {
        // formats response so we can easily display child quantity/variant selection
        return result?.data?.map((item: SfccVariant) => {
          const quantity = variant?.bundledProductItems.find(
            (childProduct: SfccVariant) => childProduct.productId === item.id,
          )?.quantity;
          return {
            ...item,
            quantity,
            variationValues: getDisplayVariationValues(item?.variationAttributes, item?.variationValues),
          };
        });
      },
    },
  );

  // get bundle product data for wishlist page
  const { data: productBundleData, isLoading: productBundleIsLoading } = useProduct(
    {
      parameters: {
        id: variant?.id,
        allImages: false,
      },
    },
    {
      enabled: Boolean(variant?.type?.bundle && !productBundleIds),
    },
  );

  return (
    <Stack spacing={1.5} flex={1} {...props}>
      {displayBonusProductLabel && (
        <Text lineHeight={1} color="black.600" fontSize="sm">
          <FormattedMessage defaultMessage="Bonus Product" id="item_attributes.label.bonus_product" />
        </Text>
      )}

      {variationValues && combineAttributeValues && (
        <Text sx={styles.colourSize}>{Object.values(variationValues).join(', ')}</Text>
      )}

      {variationValues &&
        !combineAttributeValues &&
        Object.keys(variationValues).map((key) => (
          <Text lineHeight={1} color="gray.700" fontSize="sm" key={`${key}: ${variationValues[key]}`}>
            {hideAttributeLabels ? variationValues[key] : `${key}: ${variationValues[key]}`}
          </Text>
        ))}

      {includeQuantity && (
        <Text lineHeight={1} color="gray.700" fontSize="sm">
          <FormattedMessage
            defaultMessage="Quantity: {quantity}"
            values={{ quantity: variant.quantity }}
            id="item_attributes.label.quantity"
          />
        </Text>
      )}

      {!productBundleIsLoading && productBundleData && !productBundleVariantData && (
        <Box>
          {/* Deviation from the base file (same labelled-comment convention as
                        product-view/index.tsx:659-661/1019-1022): added `?.` before `.map` —
                        `bundledProducts` is itself optional on the SDK's real Product type even
                        once `productBundleData` is truthy, which strict null checks catches and
                        the base file's plain JS did not need to guard against. This is a real,
                        narrow behaviour difference from base, not a pure typing satisfier: base
                        would throw here if `bundledProducts` were ever undefined on an otherwise
                        truthy `productBundleData`; this renders nothing instead. Directionally
                        safer (crash -> silent no-render), so left as-is rather than reverted to
                        match base's crash-on-that-shape behaviour exactly. */}
          {productBundleData?.bundledProducts?.map(({ product, quantity }: SfccVariant) => (
            <Box marginTop={2} key={product.id}>
              <Text fontSize="sm" color="gray.700" as="b">
                {product?.name}
              </Text>
              <Text fontSize="sm" color="gray.700">
                {intl.formatMessage({
                  defaultMessage: 'Qty',
                  id: 'add_to_cart_modal.label.quantity',
                })}
                : {quantity}
              </Text>
            </Box>
          ))}
        </Box>
      )}

      {!bundleVariantIsLoading && productBundleVariantData && (
        <Box>
          <Text fontSize={15} marginTop={3} fontWeight={500}>
            {intl.formatMessage({
              defaultMessage: 'Selected Options',
              id: 'item_attributes.label.selected_options',
            })}
            :
          </Text>
          {productBundleVariantData?.map(({ variationValues, name: productName, quantity, id }: SfccVariant) => {
            return (
              <Box key={id} marginTop={2}>
                <Text fontSize="sm" color="gray.700" as="b">
                  {productName}
                </Text>
                <Text fontSize="sm" color="gray.700">
                  {intl.formatMessage({
                    defaultMessage: 'Qty',
                    id: 'add_to_cart_modal.label.quantity',
                  })}
                  : {quantity}
                </Text>
                {Object.keys(variationValues).map((key) => {
                  const selectedVariant = `${key}: ${variationValues[key]}`;
                  return (
                    <Text fontSize="sm" color="gray.700" key={selectedVariant}>
                      {selectedVariant}
                    </Text>
                  );
                })}
              </Box>
            );
          })}
        </Box>
      )}

      {variant.priceAdjustments?.length > 0 && (
        <Flex alignItems="center">
          <Text lineHeight={1} color="gray.700" fontSize="sm">
            <FormattedMessage defaultMessage="Promotions" id="item_attributes.label.promotions" />
            {': '}
            <Text as="span" color="green.700">
              <FormattedNumber
                style="currency"
                currency={currency || basket?.currency || activeCurrency}
                value={variant.priceAdjustments.reduce((acc: number, adj: SfccVariant) => acc + (adj.price ?? 0), 0)}
              />
            </Text>
          </Text>
          <PromoPopover ml={2}>
            <Stack>
              {promos?.map((promo: SfccVariant) => (
                <Text key={promo?.id} fontSize="sm">
                  {promo?.calloutMsg}
                </Text>
              ))}
            </Stack>
          </PromoPopover>
        </Flex>
      )}
    </Stack>
  );
};

export default ItemAttributes;

