/**
 * SFCC-270 (plan step 2.2). Covers the two load-bearing "defaults-then-spread" contracts this
 * build's plan calls out explicitly:
 *   - item-image.tsx: a caller-supplied `width`/`mr` must win over the Zimmermann default
 *     (item-variant.css.ts's `image` part) — this is exactly what order-summary/index.jsx's
 *     (base, not-yet-overridden) `<CartItemVariantImage width="80px" mr={2} />` depends on.
 *   - item-name.tsx: a caller-supplied `color` must win over the Zimmermann default — the bug
 *     fix at this step (base had the spread BEFORE the explicit `color`, silently discarding
 *     any caller value).
 *
 * `useMultiSite` is mocked, not provided via a real MultiSiteProvider: item-name.tsx's <Link>
 * calls it internally, and its real dependency chain (`@salesforce/retail-react-app/app/
 * contexts`) fails to parse under Vitest's Vite transform — same mock, same reasoning, as
 * header/rightBar/index.test.tsx's own `vi.mock('.../use-multi-site', ...)`.
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import ItemVariantProvider from '.';
import CartItemVariantImage from './item-image';
import CartItemVariantName from './item-name';

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

const mockUseMultiSite = vi.mocked(useMultiSite);

// ChakraProvider with this project's own theme is required, not optional here — without it,
// `textStyle="productNames"` resolves against Chakra's default (empty) textStyles, and
// `useBreakpointValue` (item-price.tsx, exercised transitively were this file to render it)
// throws outright reading `theme.breakpoints` off an undefined theme. Same setup zimmButton's
// own test uses.
const renderWithProviders = (ui: React.ReactElement) =>
  render(
    <ChakraProvider theme={theme}>
      <MemoryRouter>
        <IntlProvider locale="en-AU" defaultLocale="en-AU">
          {ui}
        </IntlProvider>
      </MemoryRouter>
    </ChakraProvider>,
  );

const baseVariant = {
  id: 'variant-1',
  productName: 'Lilac Sand Dress',
  imageGroups: [
    {
      viewType: 'small',
      images: [{ alt: 'Lilac Sand Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
    },
  ],
};

describe('item-variant', () => {
  beforeEach(() => {
    mockUseMultiSite.mockReturnValue({
      site: { id: 'ZimmermannAU' },
      buildUrl: (path: string) => path,
    });
  });

  describe('CartItemVariantImage (item-image) — defaults-then-spread', () => {
    test('a caller-supplied width wins over the Zimmermann default', () => {
      const { container } = renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantImage width="321px" />
        </ItemVariantProvider>,
      );
      const box = container.firstElementChild as HTMLElement;
      expect(box).toHaveStyle({ width: '321px' });
    });

    test('a caller-supplied mr is applied (the exact regression that would break order-summary)', () => {
      const { container } = renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantImage mr="37px" />
        </ItemVariantProvider>,
      );
      const box = container.firstElementChild as HTMLElement;
      expect(box).toHaveStyle({ marginRight: '37px' });
    });
  });

  describe('CartItemVariantName (item-name) — spread-order bug fix', () => {
    test('a caller-supplied color wins over the Zimmermann default', () => {
      renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantName color="rgb(255, 0, 0)" />
        </ItemVariantProvider>,
      );
      const link = screen.getByRole('link', { name: 'Lilac Sand Dress' });
      expect(link).toHaveStyle({ color: 'rgb(255, 0, 0)' });
    });

    test('renders uppercase via textStyle="productNames" (text-transform, not literal casing)', () => {
      renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantName />
        </ItemVariantProvider>,
      );
      // Asserted on the <Heading> textStyle is actually applied to, not the nested <Link> —
      // text-transform is CSS-inherited from parent to child, and jsdom's getComputedStyle does
      // not reliably resolve inherited (as opposed to directly-applied) declarations.
      const heading = screen.getByRole('heading', { level: 2 });
      expect(heading).toHaveStyle({ textTransform: 'uppercase' });
    });
  });
});

