62	// Bypasses the real utility's own variationAttributes/variationValues matching logic — this
63	// test is about ProductItem's own render contract (does a combined value render as one node),
64	// not about re-proving getDisplayVariationValues' own correctness. See
65	// item-variant/item-attributes.tsx's own SFCC-270 docblock for combineAttributeValues' contract.
66	vi.mock('@salesforce/retail-react-app/app/utils/product-utils', async (importOriginal) => {
67	  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/utils/product-utils')>();
68	  return {
69	    ...actual,
70	    getDisplayVariationValues: () => ({ Colour: 'Lilac Sand', Size: 'One size' }),
71	  };
72	});
73	
74	const mockUseMultiSite = vi.mocked(useMultiSite);
75	
76	// ChakraProvider with this project's own theme is required, not optional here — without it,
77	// `textStyle="productNames"`/`"price"`/`"caption"` resolve against Chakra's default (empty)
78	// textStyles, and item-price.tsx's `useBreakpointValue` throws outright reading
79	// `theme.breakpoints` off an undefined theme. Same setup zimmButton's own test uses.
80	const renderWithProviders = (ui: React.ReactElement) =>
81	  render(
82	    <ChakraProvider theme={theme}>
83	      <MemoryRouter>
84	        <IntlProvider locale="en-AU" defaultLocale="en-AU">
85	          {ui}
86	        </IntlProvider>
87	      </MemoryRouter>
88	    </ChakraProvider>,
89	  );
