109	describe('ProductItem', () => {
110	  // jsdom has no matchMedia implementation, and item-price.tsx's `isDesktop` uses
111	  // useBreakpointValue internally, which calls it — a per-file polyfill, not a change to the
112	  // frozen vitest.setup.ts (Tier 1). Same pattern and reasoning as drawer-menu/index.test.tsx's
113	  // own beforeEach.
114	  beforeEach(() => {
115	    Object.defineProperty(window, 'matchMedia', {
116	      writable: true,
117	      value: vi.fn().mockImplementation((query: string) => ({
118	        matches: false,
119	        media: query,
120	        onchange: null,
121	        addListener: vi.fn(),
122	        removeListener: vi.fn(),
123	        addEventListener: vi.fn(),
124	        removeEventListener: vi.fn(),
125	        dispatchEvent: vi.fn(),
126	      })),
127	    });
128	
129	    mockUseMultiSite.mockReturnValue({
130	      site: { id: 'ZimmermannAU' },
131	      buildUrl: (path: string) => path,
132	    });
133	  });
134	
135	  test('renders the image with an alt, the name uppercase, the price, and one combined colour+size node', () => {
136	    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);
137	
138	    // Image renders with an alt.
139	    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();
140	
141	    // Name renders uppercase (textStyle="productNames" sets text-transform, not literal casing —
142	    // the DOM text content itself stays as authored). Asserted on the <Heading> textStyle is
143	    // actually applied to, not the nested <Link> — see item-variant/index.test.tsx's own note
144	    // on why (text-transform is CSS-inherited, and jsdom's getComputedStyle does not reliably
145	    // resolve inherited declarations).
146	    expect(screen.getByRole('heading', { level: 2 })).toHaveStyle({ textTransform: 'uppercase' });
147	
148	    // Price renders — DisplayPrice/CurrentPrice formats $495.00 via react-intl; rendered twice
149	    // (mobile + desktop slots both exist in the DOM under jsdom, which does not evaluate CSS
150	    // media queries — see header/rightBar/index.test.tsx's own note on this exact behaviour).
151	    expect(screen.getAllByText('$495.00').length).toBeGreaterThan(0);
152	
